# recursively print top structure without expanding values
seen=set()
def walk(o, depth=0):
    if o is None or id(o) in seen or depth>5: return
    seen.add(id(o))
    print('  '*depth, 'info', o.info, 'type', type(o.value), 'len?', len(o.value) if hasattr(o.value,'__len__') and not isinstance(o.value,(str,bytes)) else '')
    if o.attributes:
        walk(o.attributes, depth+1)
    if isinstance(o.value, list):
        for i,v in enumerate(o.value):
            if hasattr(v,'info'):
                print('  '*(depth+1), i, v.info, type(v.value))
                if i<3: walk(v, depth+2)
    elif isinstance(o.value, dict):
        for k,v in list(o.value.items())[:10]:
            if hasattr(v,'info'):
                print('  '*(depth+1), k, v.info, type(v.value))
                walk(v,depth+2)
